+		if err := db.SaveGreenhouseTaskWatch(ctx, store.GreenhouseTaskWatch{TaskID: taskID, RunID: "run-1046", Status: test.status, Stage: "review", RunObservedAt: 1000, StageObservedAt: 1000}); err != nil {
+			t.Fatal(err)
