44: func greenhouseStageLabel(snapshot greenhouseWatchSnapshot) (string, string) {
45: 	status := snapshot.Status
46: 	if snapshot.Run.Status != "" {
47: 		status = snapshot.Run.Status
48: 	}
49: 	stage := snapshot.Stage
50: 	if snapshot.Run.Stage != "" {
51: 		stage = snapshot.Run.Stage
52: 	}
53: 	if snapshot.Run.Pipeline != nil && snapshot.Run.Pipeline.Active != nil && snapshot.Run.Pipeline.Active.Stage != "" {
54: 		stage = snapshot.Run.Pipeline.Active.Stage
55: 	}
56: 	if stage == "pipeline" && status == "running" {
57: 		stage = "review"
58: 	}
59: 	return stage, status
60: }
