135: func greenhouseRunIDFromSignals(ctx context.Context, db *store.DB, task store.Task) string {
136: 	signals, err := db.TaskSignals(ctx, task.ID, 20)
137: 	if err != nil {
138: 		return ""
139: 	}
140: 	for _, signal := range signals {
141: 		if signal.Verb != "done" {
142: 			continue
143: 		}
144: 		var data struct {
145: 			RunID string `json:"greenhouse_run_id"`
146: 		}
147: 		if json.Unmarshal([]byte(signal.DataJSON), &data) == nil && data.RunID != "" {
148: 			return data.RunID
149: 		}
150: 	}
151: 	return ""
152: }
