154: func inspectGreenhouseTask(ctx context.Context, task store.Task) (greenhouseWatchSnapshot, error) {
155: 	request := []byte(`{"version":2,"op":"inspect"}`)
156: 	command := exec.CommandContext(ctx, "greenhouse", "axi")
157: 	command.Dir = task.WorktreePath
158: 	command.Stdin = bytes.NewReader(request)
159: 	command.Env = os.Environ()
160: 	output, err := command.Output()
161: 	if err != nil {
162: 		return greenhouseWatchSnapshot{}, fmt.Errorf("inspect Greenhouse in %s: %w", task.WorktreePath, err)
163: 	}
164: 	var snapshot greenhouseWatchSnapshot
165: 	if err := json.Unmarshal(output, &snapshot); err != nil {
166: 		return snapshot, fmt.Errorf("decode Greenhouse inspect: %w", err)
167: 	}
168: 	if snapshot.RunID == "" {
169: 		snapshot.RunID = snapshot.Run.ID
170: 	}
171: 	return snapshot, nil
172: }
